mapper.update:
UPDATE password_reset_tokens
SET used_at = #{now}
WHERE user_id = #{userId}
  AND used_at IS NULL

mapper.select:
UPDATE password_reset_tokens
SET used_at = #{now}
WHERE token_hash = #{tokenHash}
  AND used_at IS NULL
  AND expires_at > #{now}
RETURNING user_id

mapper.update:
UPDATE users
SET password_hash = #{passwordHash}, updated_at = NOW()
WHERE id = #{userId}

mapper.delete:
DELETE FROM password_reset_tokens
WHERE id IN (
    SELECT id
    FROM password_reset_tokens
    WHERE expires_at < #{before}
    ORDER BY expires_at
    LIMIT #{limit}
)
